SourceCode.Declaration:
/// <summary>
/// Process definition for Negative Adjustments
/// </summary>
class MwmsProcessNegativeAdjustment extends TFMProcess
{
}

Method.Source:
protected void new()
{
    MwmsLogicBlockCreateProfitLossJournal       jourBlock = MwmsLogicBlockCreateProfitLossJournal::Construct();
    MwmsLogicBlockCreateProfitLossJournalLine   lineBlock = MwmsLogicBlockCreateProfitLossJournalLine::Construct();
    MwmsLogicBlockPostInventoryJournal          postBlock = MwmsLogicBlockPostInventoryJournal::Construct();
    processName = TFMConstants::NegativeAdjustment();
    description = "@TaskletMobileWMS:ProcessdefinitionforNegativeAdju";
    super();
    this.blockCollection().addBlockAddon(lineBlock, new MwmsLogicBlockAddonNegativeQuantity());
    this.addBlock(jourBlock);
    this.addBlock(lineBlock);
    this.addBlock(postBlock);

    this.linkBlocks(jourBlock,lineBlock,'1','1');
    this.linkBlocks(lineBlock, postBlock,'1','1');
}
